import{_ as t,a,o as d,a6 as o}from"./chunks/framework.CJDy2q7X.js";const m=JSON.parse('{"title":"Upload Media","description":"","frontmatter":{"outline":false,"apiType":"rest","examples":[{"id":"rest","title":"Upload Media","query":"curl -X POST \\"https://your-domain.com/api/admin/appearance/sections/12/media\\" \\\\\\n  -H \\"Authorization: Bearer <token>\\" \\\\\\n  -F \\"file=@banner.webp\\"\\n","response":"{\\n  \\"sectionId\\": 12,\\n  \\"path\\": \\"storage/theme/12/8f2c1d4b.webp\\",\\n  \\"type\\": \\"image\\",\\n  \\"message\\": \\"Media uploaded successfully.\\"\\n}\\n"},{"id":"rest-video","title":"Upload a Video","query":"curl -X POST \\"https://your-domain.com/api/admin/appearance/sections/12/media\\" \\\\\\n  -H \\"Authorization: Bearer <token>\\" \\\\\\n  -F \\"file=@promo.mp4\\"\\n","response":"{\\n  \\"sectionId\\": 12,\\n  \\"path\\": \\"storage/theme/12/1a9e77c0.mp4\\",\\n  \\"type\\": \\"video\\",\\n  \\"message\\": \\"Media uploaded successfully.\\"\\n}\\n"}]},"headers":[],"relativePath":"api/rest-api/admin/appearance/sections/media.md","filePath":"api/rest-api/admin/appearance/sections/media.md","lastUpdated":1789385991000}'),i={name:"api/rest-api/admin/appearance/sections/media.md"};function r(s,e,n,h,c,p){return d(),a("div",null,e[0]||(e[0]=[o('<h1 id="upload-media" tabindex="-1">Upload Media <a class="header-anchor" href="#upload-media" aria-label="Permalink to &quot;Upload Media&quot;">​</a></h1><p>Stores one image or video against a section and returns the path to record in its options. This endpoint is REST only — a binary upload cannot be carried over GraphQL.</p><p>Uploading does not change what the section shows. The file becomes part of the section when its path appears in the options sent to <a href="/api/rest-api/admin/appearance/sections/draft.html">Stage edits</a> or <a href="/api/rest-api/admin/appearance/sections/update.html">Update section</a>.</p><h2 id="endpoint" tabindex="-1">Endpoint <a class="header-anchor" href="#endpoint" aria-label="Permalink to &quot;Endpoint&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Method</th><th>Path</th><th>Purpose</th></tr></thead><tbody><tr><td><code>POST</code></td><td><code>/api/admin/appearance/sections/{id}/media</code></td><td>Upload media for a section</td></tr></tbody></table><p>Send as <code>multipart/form-data</code>.</p><h2 id="path-parameters" tabindex="-1">Path parameters <a class="header-anchor" href="#path-parameters" aria-label="Permalink to &quot;Path parameters&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Parameter</th><th>Description</th></tr></thead><tbody><tr><td><code>id</code></td><td>Section the media belongs to.</td></tr></tbody></table><h2 id="request-body" tabindex="-1">Request body <a class="header-anchor" href="#request-body" aria-label="Permalink to &quot;Request body&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Field</th><th>Type</th><th>Required</th><th>Description</th></tr></thead><tbody><tr><td><code>file</code></td><td>binary</td><td>Yes</td><td>The image or video to store.</td></tr></tbody></table><h2 id="response-fields" tabindex="-1">Response fields <a class="header-anchor" href="#response-fields" aria-label="Permalink to &quot;Response fields&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Field</th><th>Type</th><th>Description</th></tr></thead><tbody><tr><td><code>sectionId</code></td><td>integer</td><td>Section the file was stored against.</td></tr><tr><td><code>path</code></td><td>string</td><td>Stored path to record in the section&#39;s options.</td></tr><tr><td><code>type</code></td><td>string</td><td><code>image</code> or <code>video</code>, decided from the file itself.</td></tr><tr><td><code>message</code></td><td>string</td><td>Confirmation text.</td></tr></tbody></table><h2 id="use-cases" tabindex="-1">Use cases <a class="header-anchor" href="#use-cases" aria-label="Permalink to &quot;Use cases&quot;">​</a></h2><ul><li><strong>Add a slide to an image carousel</strong> — upload, then stage options carrying the returned <code>path</code> alongside the slide&#39;s link and title.</li></ul><h2 id="best-practices" tabindex="-1">Best practices <a class="header-anchor" href="#best-practices" aria-label="Permalink to &quot;Best practices&quot;">​</a></h2><ul><li><strong>Record the returned <code>path</code> verbatim.</strong> It is the value the storefront resolves; rewriting or re-hosting it breaks the image.</li><li><strong>Files nothing points at are cleaned up.</strong> An upload whose path never reaches the section&#39;s published or staged options is removed when the section is next saved, so upload as part of an edit rather than in advance.</li><li><strong><code>type</code> is derived from the file, not from the section.</strong> A video uploaded to an image carousel still returns <code>video</code>; it is up to the client to put the path in a field that accepts it.</li></ul><h2 id="errors" tabindex="-1">Errors <a class="header-anchor" href="#errors" aria-label="Permalink to &quot;Errors&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Status</th><th>When</th></tr></thead><tbody><tr><td><code>404</code></td><td>No section with this ID.</td></tr><tr><td><code>422</code></td><td>No <code>file</code> part in the request.</td></tr></tbody></table><h2 id="permissions" tabindex="-1">Permissions <a class="header-anchor" href="#permissions" aria-label="Permalink to &quot;Permissions&quot;">​</a></h2><p>Requires <code>appearance.sections.edit</code>.</p>',20)]))}const u=t(i,[["render",r]]);export{m as __pageData,u as default};
